<?php require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../repositories/userPDO.php';require_once __DIR__.'/../includes/auth.php';$pdo=openDatabase();$admin=requireLogin($pdo);requireRole($admin,['Administrator']);$id=filter_input(INPUT_GET,'user_id',FILTER_VALIDATE_INT);$account=$id?findUserById($pdo,$id):false;if(!$account){http_response_code(404);exit('Account not found.');}require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/nav.php';?><main class="container py-4"><h1>Manage account</h1><dl><dt>Name</dt><dd><?=htmlspecialchars($account['full_name'],ENT_QUOTES,'UTF-8')?></dd><dt>Email</dt><dd><?=htmlspecialchars($account['email'],ENT_QUOTES,'UTF-8')?></dd><dt>Role</dt><dd><?=$account['role']?></dd><dt>Status</dt><dd><?=$account['status']?></dd></dl><form method="post" action="update-role.php"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><label>New role<select name="role" class="form-select"><?php foreach(['Student','Tutor','Administrator'] as $r):?><option <?=$r===$account['role']?'selected':''?>><?=$r?></option><?php endforeach;?></select></label><button class="btn btn-primary">Save role</button></form><form method="post" action="update-status.php"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><input type="hidden" name="status" value="<?=$account['status']==='Active'?'Inactive':'Active'?>"><button class="btn btn-warning"><?=$account['status']==='Active'?'Deactivate':'Activate'?> account</button></form><form method="post" action="delete-user.php"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8')?>"><input type="hidden" name="user_id" value="<?=$id?>"><button class="btn btn-danger">Confirm delete account</button></form><a href="manage-users.php">Back to users</a></main><?php require __DIR__.'/../includes/footer.php';?>
